hostname = c.zhangle.com, live.inst-service.htsc.com, geetest.htsc.com, 119.29.29.*

[Rewrite]
request if ${url} ~= /^https?:\/\/c\.zhangle\.com\/pic\/mktg\/diversity\/.+\.jpg$/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/live\.inst-service\.htsc\.com\/live/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/geetest\.htsc\.com:8888\/pre_get_token/i then reject(200)
request if ${url} ~= /^https?:\/\/119\.29\.29\.\d+\/d/i then reject(200)
